private void enlarge(final int size) {
    // Calculate the new size of the byte vector
    int newSize = this.length + size;

    // Create a new array with the new size
    byte[] newData = new byte[newSize];

    // Copy the existing data from this.data to the new array
    System.arraycopy(this.data, 0, newData, 0, this.length);

    // Update this.data to point to the new array
    this.data = newData;

    // Update this.length to reflect the new data array
    this.length = newSize;
}

