public void format(LoggingEvent event){
    StringBuffer buffer = new StringBuffer();
    // Append the date and time of the event to the buffer
    SimpleDateFormat sdf = new SimpleDateFormat("dd MMM yyyy HH:mm:ss");
    buffer.append(sdf.format(event.getTimeStamp()));
    buffer.append(" [");
    buffer.append(event.getThreadName());
    buffer.append("] ");
    buffer.append(event.getLevel().toString());

    // Check if the event has an exception
    Throwable throwable = event.getThrowableInformation() != null ? event.getThrowableInformation().getThrowable() : null;
    if (throwable != null){
        buffer.append(" - ");
        buffer.append(throwable.getMessage());
        buffer.append(" : ");
        buffer.append(throwable.getClass().getName());
    }

    // Append the logging message to the buffer
    buffer.append(" - ");
    buffer.append(event.getMessage());

    // Return the formatted string
    return buffer.toString();
}

