private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // define the circulator to use
    OuterFaceCirculator circulator = new OuterFaceCirculator(start, stop, dir);

    // loop until the circulator reaches the stop node
    while (circulator.hasNext()) {
        Node node = circulator.next();
        // if the predicate holds for the current node, return the circulator
        if (predicate.apply(node)) {
            return circulator;
        }
    }

    // the circulator did not reach the stop node, return an empty circulator
    return new OuterFaceCirculator(stop, stop, dir);
}

