private List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {

    // Initialize the list of minimal separators for each edge
    List<Pair<List<Pair<Integer,Integer>>,E>> separators = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E e : graph.edgeSet()) {
        // Compute the neighborhood of the edge
        Set<E> neighbors = graph.neighborOf(e);

        // Initialize the list of minimal separators for the edge
        List<Pair<List<Pair<Integer,Integer>>,E>> separatorsForEdge = new ArrayList<>();

        // Iterate over all neighbors of the edge
        for (E neighbor : neighbors) {
            // Construct the separator
            Pair<List<Pair<Integer,Integer>>,E> separator = constructSeparator(e, neighbor);

            // Add the separator to the list of minimal separators for the edge
            separatorsForEdge.add(separator);
        }

        // Add the list of minimal separators for the edge to the overall list of minimal separators
        separators.add(separatorsForEdge);
    }

    // Return the list of minimal separators for every edge
    return separators;
}

public Pair<List<Pair<Integer,Integer>>,E> constructSeparator(E e, E n) {
    List<Integer> separators = new ArrayList<>();

    // Get the vertices of the edge and the neighbor
    int[] verticesOfE = graph.getVertices(e);
    int[] verticesOfN = graph.getVertices(n);

    // Find the vertices that are not in both e and n
    Set<Integer> verticesNotInEandN = new HashSet<>(Arrays.asList(verticesOfE));
    verticesNotInEandN.retainAll(Arrays.asList(verticesOfN));

    // Add the vertices that are not in both to the separator
    separators.addAll(verticesNotInEandN);

    // Return the separator
    return new Pair<>(separators,e);
}

