private List < Integer > computeLowerBounds(List < K > keys) {
    // Initialize a list to store the lower bounds
    List < Integer > lowerBounds = new ArrayList < Integer > (keys.size());

    // Find the maximum lower bound for each key
    for (int i = 0; i < keys.size(); i++) {
        // Find the largest key that is less than or equal to the current key
        int j = i - 1;
        while (j >= 0 && keys.get(j).compareTo(keys.get(i)) > 0) {
            j--;
        }

        // Set the lower bound to the maximum key found
        lowerBounds.add(j + 1);
    }

    return lowerBounds;
}

