private List<Integer> computeUpperBounds(List<K> keys) {
    if (keys == null || keys.isEmpty()) {
        throw new IllegalArgumentException("Keys must be a non-empty list");
    }

    // Sort the keys in ascending order
    Collections.sort(keys, Comparator.naturalOrder());

    // Initialize the upper bounds to the maximum value of the key type
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (int i = 0; i < keys.size(); i++) {
        upperBounds.add(Integer.MAX_VALUE);
    }

    // Compute the minimum lower bound for every key by iterating through the sorted keys
    for (int i = 0; i < keys.size(); i++) {
        // If the current key is greater than the upper bound of the previous key,
        // then update the upper bound of the previous key
        if (keys.get(i) > upperBounds.get(i - 1)) {
            upperBounds.set(i - 1, keys.get(i));
        }
    }

    return upperBounds;
}

