    // Find the index of the extension separator character '.'
    int extensionSeparatorIndex = filename.lastIndexOf(EXTENSION_SEPARATOR);
    if (index < 0 || extensionSeparatorIndex < 0 || extensionSeparatorIndex > index) {
        // If the extension separator character is not found, or if the extension separator character follows a directory separator,
